// Platform fee (a.k.a. moderator commission). A global percentage the moderator
// sets, added on top of the consumer's order subtotal and shown as a
// "Platform fee". Lives in the single-row platform_settings table; each order
// stamps the resolved rupee amount in orders.platform_fee.

import type { SupabaseClient } from '@supabase/supabase-js'

// Resolve the rupee fee for a given subtotal. Rounded to whole rupees; never
// negative. pct is a percentage (5 → 5%).
export function computePlatformFee(subtotal: number, pct: number): number {
  if (!pct || pct <= 0 || !Number.isFinite(pct)) return 0
  if (!subtotal || subtotal <= 0) return 0
  return Math.round((subtotal * pct) / 100)
}

// Read the current fee percentage. Best-effort: if the table doesn't exist yet
// (migration not applied) or anything fails, fall back to 0 so checkout and
// payments are never blocked by the fee.
export async function getPlatformFeePercent(supabase: SupabaseClient): Promise<number> {
  try {
    const { data, error } = await supabase
      .from('platform_settings')
      .select('fee_percent')
      .eq('id', 1)
      .maybeSingle()
    if (error) return 0
    const pct = Number(data?.fee_percent)
    return Number.isFinite(pct) && pct > 0 ? pct : 0
  } catch {
    return 0
  }
}

      pickup_location: typeof pickupLocation === 'string' ? pickupLocation.slice(0, 200) : null,
      status: 'pending',
      payment_method: paymentMethod,
      payment_status: 'pending',
      delivery_type: deliveryType,
      delivery_status: deliveryType === 'home_delivery' ? 'unassigned' : null,
      delivery_address: deliveryAddress,
      delivery_city: deliveryCity,
      delivery_landmark: deliveryLandmark,
      delivery_pincode: deliveryPincode,
      delivery_alt_phone: deliveryAltPhone,
      handover_otp: sharedHandoverOtp,
      // Fee is paid once per cart, so we stamp it on the first row only.
      // sum(delivery_fee) and sum(rider_payout) over a batch === one fee.
      delivery_fee: 0,
      rider_payout: 0,
    })
  }

  if (rows.length > 0 && deliveryFee > 0) {
    rows[0].delivery_fee = deliveryFee
    rows[0].rider_payout = deliveryFee
  }

  // Platform fee (moderator commission) — a % charged PER ITEM and stamped on
  // each row (unlike delivery_fee, which is one-per-cart on the first row). Per
  // row means a single-item cancel/decline withholds or refunds exactly that
  // item's own fee, and the per-item fees the buyer sees at checkout sum to what
  // we charge. Resolved server-side; 0 unless the moderator set a fee. Only
  // touched when a fee applies, so the column is never referenced before its
  // migration runs — and when it is, every row in the batch carries it (even 0)
  // so the bulk insert has a uniform column set.
  const feePercent = await getPlatformFeePercent(supabase)
  let platformFee = 0
  if (feePercent > 0) {
    for (const r of rows) {
      const fee = computePlatformFee(Number(r.total_price) || 0, feePercent)
      r.platform_fee = fee
      platformFee += fee
    }
  }

  // Atomic stock claim. decrement_stock returns false if the listing went
  // below zero (or vanished). On any failure we revert prior claims so we
  // don't leak inventory.
  const claimed: Array<{ listingId: string; qty: number }> = []
  const revertClaims = async () => {
    for (const c of claimed) {
      try {
        await supabase.rpc('increment_stock', { p_listing_id: c.listingId, p_qty: c.qty })
      } catch (e) {
        console.error('[YFF] increment_stock revert failed:', e)
      }
    }
  }
  for (const item of items) {
    const listing = listingById.get(item.listingId)!
    const { data: ok, error: rpcErr } = await supabase.rpc('decrement_stock', {
      p_listing_id: item.listingId,
      p_qty: item.qty,
    })
    if (rpcErr) {
      console.error('[YFF] decrement_stock rpc failed:', rpcErr.message)
      await revertClaims()
      return bad('Could not place order. Please try again.', 500)
    }
    if (!ok) {
      await revertClaims()
      return bad(`${listing.name} just sold out. Please reduce the quantity and try again.`)
    }
    claimed.push({ listingId: item.listingId, qty: item.qty })
  }

  const { data: inserted, error: insertErr } = await supabase
    .from('orders')
    .insert(rows)
    .select('id, order_code')

  if (insertErr || !inserted) {
    console.error('[YFF] place-order insert failed:', insertErr?.message)
    // Roll the stock back so the row isn't lost.
    await revertClaims()
    return bad('Could not place order. Please try again.', 500)
  }

  const orderIds = inserted.map((r) => r.id)
  return NextResponse.json({
    ok: true,
    orderIds,
    orderCodes: inserted.map((r) => (r as { order_code?: string | null }).order_code).filter(Boolean),
    total,
    deliveryFee,
    platformFee,
    grandTotal: total + deliveryFee + platformFee,
    // Guests get a short-lived token bound to these orders so they can finish
    // the Razorpay create/verify pair without a session cookie.
    ...(isGuest ? { guestToken: createGuestOrderToken(orderIds) } : {}),
  })
}

  ]
  const [reason, setReason] = useState('')

  // Refund preview, shown BEFORE the buyer confirms. A buyer cancel refunds the
  // produce price only (= total_price) and WITHHOLDS the platform fee. Mirrors
  // the cancel API and the shared CancelOrderModal on the orders list.
  const wasPaid = isOrderPaid(order.payment_status) || isPaymentClaimed(order.payment_status)
  const refundAmount = Math.max(0, Number(order.total_price) || 0)
  const platformFeeWithheld = Math.max(0, Number(order.platform_fee) || 0)

  return (
    <div className="fixed inset-0 z-50 bg-black/50 flex items-end sm:items-center justify-center p-4">
      <div className="bg-white rounded-2xl w-full max-w-sm p-5 space-y-4">
        <div>
          <p className="text-base font-extrabold text-gray-900">{L('Cancel order', 'ఆర్డర్ రద్దు')}</p>
          <p className="text-xs text-gray-500 mt-1 leading-snug">
            {L('Please tell the farmer why. If you have already paid, you will be refunded automatically.', 'రైతుకు కారణం చెప్పండి. మీరు ఇప్పటికే చెల్లించి ఉంటే, డబ్బు ఆటోమేటిక్‌గా తిరిగి వస్తుంది.')}
          </p>
        </div>

        {/* "Are you sure?" warning — cancelling can't be undone. */}
        <div className="bg-amber-50 border border-amber-300 rounded-xl px-3 py-2.5">
          <p className="text-xs font-bold text-amber-800 leading-snug">
            ⚠️ {L('Are you sure you want to cancel this order? This cannot be undone.', 'మీరు ఖచ్చితంగా ఈ ఆర్డర్‌ను రద్దు చేయాలనుకుంటున్నారా? దీన్ని తిరిగి మార్చలేరు.')}
          </p>
        </div>

        {/* Refund preview — what the buyer will get back if they go ahead. */}
        {wasPaid && (
          <div className="bg-green-50 border border-green-200 rounded-2xl px-4 py-3 space-y-1">
            <div className="flex items-center justify-between text-sm">
              <span className="text-gray-700 font-semibold">{L('You will be refunded', 'మీకు తిరిగి వచ్చేది')}</span>
              <span className="font-extrabold text-green-800">₹{refundAmount}</span>
            </div>
            {platformFeeWithheld > 0 && (
              <>
                <div className="flex items-center justify-between text-xs">
                  <span className="text-gray-500">{L('Platform fee (not refunded)', 'ప్లాట్‌ఫామ్ ఫీజు (తిరిగి ఇవ్వబడదు)')}</span>
                  <span className="font-bold text-red-600">₹{platformFeeWithheld}</span>
                </div>
                <p className="text-[11px] text-gray-400 leading-snug pt-0.5">
                  {L('Since you are cancelling, the platform fee covers the payment & service cost and is not refunded.', 'మీరు రద్దు చేస్తున్నందున, ప్లాట్‌ఫామ్ ఫీజు చెల్లింపు, సేవా ఖర్చును కవర్ చేస్తుంది, తిరిగి ఇవ్వబడదు.')}
                </p>
              </>
            )}
            <p className="text-[11px] text-gray-400 leading-snug pt-0.5">
              {L('The refund reaches your account in 3–5 business days.', 'రీఫండ్ 3–5 పని దినాలలో మీ ఖాతాకు జమ అవుతుంది.')}
            </p>
          </div>
        )}

        <div className="flex flex-wrap gap-2">
          {presets.map((p) => (
            <button
              key={p}
              type="button"
              onClick={() => setReason(p)}
              className={`text-[11px] font-semibold px-3 py-1.5 rounded-full border ${
                reason === p
                  ? 'bg-green-700 text-white border-green-700'
                  : 'bg-gray-50 text-gray-700 border-gray-200 active:bg-gray-100'
              }`}
            >
              {p}
            </button>
          ))}
        </div>

        <textarea
          value={reason}
          onChange={(e) => setReason(e.target.value)}
          rows={3}
          maxLength={300}
          placeholder={L('Reason (optional)', 'కారణం (ఐచ్ఛికం)')}
          className="w-full border border-gray-200 rounded-xl px-3 py-2 text-sm focus:border-green-500 focus:outline-none resize-none"
        />

        <div className="grid grid-cols-2 gap-2">
          <button
            onClick={onClose}
            disabled={cancelling}
            className="border border-gray-300 text-gray-700 font-bold py-3 rounded-xl text-sm active:bg-gray-50 disabled:opacity-50"
          >
            {L('Keep order', 'ఆర్డర్ ఉంచు')}
          </button>
          <button
            onClick={() => onConfirm(reason.trim())}
            disabled={cancelling}
            className="bg-red-600 text-white font-bold py-3 rounded-xl text-sm active:bg-red-700 disabled:opacity-50"
          >
            {cancelling ? L('Cancelling...', 'రద్దు...') : L('Cancel order', 'రద్దు చేయి')}
          </button>
        </div>
      </div>
    </div>
  )
}

// Printable payment receipt. Shown as an overlay; the print stylesheet hides
// everything except .yff-receipt so "Print / Save as PDF" produces a clean
// one-page receipt on both phones and laptops.
function ReceiptOverlay({ order, onClose }: { order: Order; onClose: () => void }) {
  const { lang, L } = useLang()
  const placed = new Date(order.created_at).toLocaleString('en-IN', {
    day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit',
  })
  const paymentRef = order.razorpay_payment_id || order.order_code || order.id
  // Platform fee the buyer paid for this order (stamped per row); the true
  // total paid = item price + platform fee.
  const platformFeePaid = Math.max(0, Number(order.platform_fee) || 0)
  const totalPaid = (Number(order.total_price) || 0) + platformFeePaid

  return (
    <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4 overflow-y-auto">
      <style>{`@media print {
        body * { visibility: hidden !important; }
        .yff-receipt, .yff-receipt * { visibility: visible !important; }
        .yff-receipt { position: absolute; left: 0; top: 0; width: 100%; box-shadow: none !important; }
        .yff-no-print { display: none !important; }
      }`}</style>

      <div className="yff-receipt bg-white rounded-2xl w-full max-w-sm p-6 my-auto">
        <div className="text-center border-b border-dashed border-gray-300 pb-3">
          <p className="text-lg font-extrabold text-green-700">YourFamilyFarmer</p>
          <p className="text-[11px] text-gray-500">{L('Payment Receipt', 'చెల్లింపు రసీదు')}</p>
        </div>

        <div className="py-3 space-y-1.5 text-xs">
          <div className="flex justify-between"><span className="text-gray-500">{L('Order ID', 'ఆర్డర్ ID')}</span><span className="font-mono font-bold text-gray-900">{order.order_code || order.id.slice(0, 8)}</span></div>
          <div className="flex justify-between"><span className="text-gray-500">{L('Date', 'తేదీ')}</span><span className="font-semibold text-gray-900">{placed}</span></div>
          {order.farmer && (
            <div className="flex justify-between"><span className="text-gray-500">{L('Farmer', 'రైతు')}</span><span className="font-semibold text-gray-900 text-right">{order.farmer.name} · {order.farmer.village}</span></div>
          )}
          <div className="flex justify-between"><span className="text-gray-500">{L('Payment', 'చెల్లింపు')}</span><span className="font-semibold text-gray-900">{order.payment_method_detail || (order.payment_method === 'cod' ? 'Cash on Delivery' : isOnlinePayment(order.payment_method) ? 'UPI' : order.payment_method || '—')}</span></div>
        </div>

        <div className="border-t border-dashed border-gray-300 py-3 space-y-1.5">
          <div className="flex justify-between text-xs">
            <span className="text-gray-700">{localizeName(order.produce_name, lang)} × {order.quantity} {order.unit || 'kg'}</span>
            <span className="font-semibold text-gray-900">₹{order.total_price ?? 0}</span>
          </div>
          {platformFeePaid > 0 && (
            <div className="flex justify-between text-xs">
              <span className="text-gray-500">{L('Platform fee', 'ప్లాట్‌ఫామ్ ఫీజు')}</span>
              <span className="font-semibold text-gray-900">₹{platformFeePaid}</span>
            </div>
          )}
        </div>

        <div className="border-t-2 border-gray-900 pt-2 flex justify-between items-center">
          <span className="text-sm font-bold text-gray-900">{L('Total Paid', 'మొత్తం చెల్లించారు')}</span>
          <span className="text-lg font-extrabold text-green-700">₹{totalPaid}</span>
        </div>

        <div className="mt-3 text-center">
          <span className="inline-block text-[10px] font-bold px-3 py-1 rounded-full bg-green-100 text-green-800">{L('✓ PAID', 'చెల్లించారు')}</span>
        </div>

        <p className="text-[9px] text-gray-400 text-center mt-3 break-all">Ref: {paymentRef}</p>
        <p className="text-[10px] font-semibold text-green-700 text-center mt-2">{L('Thank you for supporting our farmers — GoGrameen Team 🌱', 'మా రైతులకు మద్దతు ఇచ్చినందుకు ధన్యవాదాలు — గోగ్రామీణ్ టీం')}</p>

        <div className="yff-no-print mt-5 grid grid-cols-2 gap-2">
          <button onClick={onClose} className="border border-gray-300 text-gray-700 font-bold py-2.5 rounded-xl text-sm active:bg-gray-50">{L('Close', 'మూసివేయి')}</button>
          <button onClick={() => window.print()} className="bg-green-700 text-white font-bold py-2.5 rounded-xl text-sm active:bg-green-800">{L('Print', 'ప్రింట్')}</button>
        </div>
      </div>
    </div>
  )
}

if (!id || !UUID_RE.test(id)) return NextResponse.json({ error: 'Invalid order id.' }, { status: 400 })

const supabase = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!,
)

const { data: order, error } = await supabase
  .from('orders')
  .select(
    'id, order_code, consumer_id, produce_name, produce_listing_id, quantity, unit, total_price, platform_fee, pickup_location, status, payment_method, payment_method_detail, payment_status, paid_at, confirmed_at, razorpay_payment_id, refund_status, refund_id, refund_amount, refunded_at, decline_reason, payment_proof_path, created_at, farmer_id, delivery_type, delivery_status, delivery_address, delivery_city, delivery_landmark, delivery_pincode, delivery_alt_phone, delivery_boy_id, handover_otp, assigned_at, picked_up_at, out_for_delivery_at, delivered_at, collected_at, shipped_at, received_at, fulfillment_date',
  )
  .eq('id', id)
  .maybeSingle()

if (error) return NextResponse.json({ error: error.message }, { status: 500 })
if (!order) return NextResponse.json({ error: 'Order not found.' }, { status: 404 })
if (order.consumer_id !== session.consumerId) {
  return NextResponse.json({ error: 'Not your order.' }, { status: 403 })
}

// Manual farmer join (no FK on orders.farmer_id → farmers.id, so embedding fails)
let farmer: { name: string; slug: string; village: string; phone: string | null; upi_id: string | null } | null = null
if (order.farmer_id) {
  const { data: f } = await supabase
    .from('farmers')
    .select('id, name, slug, village, phone, upi_id')
    .eq('id', order.farmer_id)
    .maybeSingle()
  if (f) {

    if (isPaymentClaimed(o.payment_status))
      return `${m} ⏳ Awaiting farmer confirmation`
    if (o.payment_status === 'failed') return `${m} ✕ Not received`
    return L('Payment Pending', 'చెల్లింపు పెండింగ్')
  }
  return o.payment_method ?? '—'
}

const orderDate = order
  ? new Date(order.created_at).toLocaleDateString('en-IN', {
      day: 'numeric', month: 'short', year: 'numeric',
    })
  : ''
const orderTime = order
  ? new Date(order.created_at).toLocaleTimeString('en-IN', {
      hour: '2-digit', minute: '2-digit',
    })
  : ''

const whatsappHref = order?.farmer?.phone && order?.produce_name
  ? `https://wa.me/91${order.farmer.phone.replace(/\D/g, '').slice(-10)}?text=${encodeURIComponent(
      `Hello ${order.farmer.name} anna, regarding my order of ${order.produce_name} on ${orderDate}.`,
    )}`
  : null

return (
  <main className="min-h-screen bg-gray-50 pb-16">
    <div className="bg-green-900 px-4 pt-6 pb-10">
      <div className="flex items-center justify-between mb-4">
        <Link href="/consumer/orders" className="text-green-300 text-sm flex items-center gap-1">
          ← {L('Back', 'వెనక్కు')}
        </Link>
        <LanguageToggle />
      </div>
      <h1 className="text-white text-xl font-extrabold leading-tight">
        {L('Order details', 'ఆర్డర్ వివరాలు')}
      </h1>
    </div>

    <div className="px-4 -mt-5 space-y-4 max-w-lg mx-auto">
      {state.status === 'anonymous' ? (
        <div className="bg-white rounded-2xl border border-gray-100 p-6 text-center space-y-4">
          <div className="text-5xl">🔒</div>
          <p className="font-bold text-gray-900">Log in to view this order</p>
          <button
            onClick={openAuth}
            className="w-full bg-green-700 text-white font-bold py-3.5 rounded-xl text-sm active:bg-green-800"
          >
            {L('Log in', 'లాగిన్')}
          </button>
        </div>
      ) : loading ? (
        <div className="bg-white rounded-2xl border border-gray-100 p-6 text-center text-sm text-gray-500">
          {L('Loading...', 'లోడ్ అవుతోంది')}
        </div>
      ) : error ? (
        <div className="bg-white rounded-2xl border border-red-100 p-6 text-sm text-red-600">{error}</div>
      ) : !order ? null : (
        <>
          {/* Status + payment summary */}
          <div className="bg-white rounded-2xl border border-gray-100 p-4 space-y-3">
            <div className="flex items-start justify-between gap-2">
              <div>
                <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide">Order</p>
                {order.order_code && (
                  <p className="text-[11px] font-mono font-semibold text-gray-400">{order.order_code}</p>
                )}
                <p className="text-base font-extrabold text-gray-900 leading-tight">
                  {localizeName(order.produce_name, lang) || '—'}
                </p>
                <p className="text-xs text-gray-500 mt-0.5">
                  {order.quantity} {order.unit || 'kg'}
                  {order.total_price ? ` · ₹${order.total_price}` : ''}
                </p>
              </div>
              <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full whitespace-nowrap ${statusColor(order.status)}`}>
                {statusLabel(order.status)}
              </span>
            </div>

            <div className="grid grid-cols-2 gap-3 pt-1 border-t border-gray-100 mt-3">
              <div>
                <p className="text-[10px] font-bold text-gray-400 uppercase">Placed</p>
                <p className="text-xs font-semibold text-gray-700">{orderDate}</p>
                <p className="text-[11px] text-gray-500">{orderTime}</p>
              </div>
              <div>
                <p className="text-[10px] font-bold text-gray-400 uppercase">Payment</p>
                <p className="text-xs font-semibold text-gray-700">{paymentLabel(order)}</p>
              </div>
            </div>

            {order.pickup_location && (
              <div className="pt-1 border-t border-gray-100 mt-1">
                <p className="text-[10px] font-bold text-gray-400 uppercase">Pickup</p>
                <p className="text-xs font-semibold text-gray-700">📍 {order.pickup_location}</p>
              </div>
            )}

            {isOrderPaid(order.payment_status) && (
              <button
                onClick={() => setShowReceipt(true)}
                className="mt-3 w-full border border-green-600 text-green-700 font-bold py-2.5 rounded-xl text-sm active:bg-green-50"
              >
                🧾 {L('View receipt', 'రసీదు చూడండి')}
              </button>
            )}

            {canCancel && (
              <button
                onClick={() => setShowCancel(true)}
                disabled={cancelling}
                className="mt-2 w-full border border-red-300 text-red-600 font-bold py-2.5 rounded-xl text-sm active:bg-red-50 disabled:opacity-50"
              >
                {cancelling ? L('Cancelling...', 'రద్దు చేస్తోంది...') : L('✕ Cancel order', 'ఆర్డర్ రద్దు')}
              </button>
            )}

          </div>

          {/* Pickup / Delivery date the farmer scheduled for this order. */}
          {order.fulfillment_date && order.status !== 'declined' && order.status !== 'cancelled' && (
            <div className="bg-green-50 border border-green-200 rounded-2xl p-4 flex items-center gap-3">
              <span className="text-2xl">📅</span>
              <div>
                <p className="text-[10px] font-bold text-green-700 uppercase tracking-wide">
                  {order.delivery_type === 'home_delivery'
                    ? L('Delivery date', 'డెలివరీ తేదీ')
                    : L('Pickup date', 'పికప్ తేదీ')}
                </p>

'use client'

import Link from 'next/link'
import { useLang } from '@/lib/LanguageContext'
import { localizeName } from '@/lib/localizeName'
import type { MyReview } from '@/components/consumer/ProduceReviewBox'

type DeliveryStatus = 'unassigned' | 'assigned' | 'picked_up' | 'out_for_delivery' | 'delivered'

export type ConsumerOrder = {
  id: string
  order_code: string | null
  produce_name: string | null
  produce_listing_id?: string | null
  quantity: number | null
  unit: string | null
  total_price: number | null
  // Platform fee stamped on this row (cart's first row carries it, 0 on the
  // rest). Withheld — not refunded — when the BUYER cancels, so the cancel modal
  // can preview the deduction.
  platform_fee?: number | null
  pickup_location: string | null
  status: 'pending' | 'approved' | 'declined' | 'cancelled'
  payment_method: string | null
  payment_status: string | null
  refund_status: string | null
  decline_reason: string | null
  payment_proof_path: string | null
  created_at: string
  farmer_id: string
  farmer?: {
    name: string
    slug: string
    village: string
    phone: string | null
    upi_id: string | null
  } | null
  delivery_type?: 'self_pickup' | 'home_delivery' | 'courier' | null
  delivery_status?: DeliveryStatus | null
  shipped_at?: string | null
  collected_at?: string | null
  received_at?: string | null
  delivered_at?: string | null
  // When the buyer acknowledged a declined/cancelled order (moves it to history).
  acknowledged_at?: string | null
  // The buyer's own feedback for this order, if they've left any.
  my_review?: MyReview | null
}

// A completed order — delivered / picked up / received, and not declined or
// cancelled. Feedback on these is published as a public produce rating; feedback
// on any other order is kept private. Mirrors the gate in /api/produce-reviews.
export const isCompleted = (o: ConsumerOrder) =>
  o.status !== 'declined'
  && o.status !== 'cancelled'
  && (o.delivery_status === 'delivered' || !!o.collected_at || !!o.received_at || !!o.delivered_at)

// An order is "resolved" once it reaches a terminal state: delivered (home
// delivery), picked up (self-pickup) or received (courier). A farmer-DECLINED
// order is only resolved once the buyer has acknowledged it — until then it
// stays in the Active list with an Acknowledge button so a decline never
// silently drops into history. A buyer-CANCELLED order is resolved straight
// away: the buyer cancelled it themselves, so it goes to their history at once
// (it's the FARMER who now acknowledges that cancellation, on their dashboard).
// Active = everything else still in progress. Shared so the active list and the
// history page agree on where each order belongs.
export const isResolved = (o: ConsumerOrder) =>
  (o.status === 'declined' && !!o.acknowledged_at)
  || o.status === 'cancelled'
  || o.delivery_status === 'delivered'
  || !!o.collected_at
  || !!o.received_at

// A farmer-declined order still waiting on the buyer's acknowledgement. Shown in
// the Active list with an Acknowledge button. A buyer's own cancellation does
// NOT need their acknowledgement — that's resolved on the farmer's side instead.
export const needsAcknowledge = (o: ConsumerOrder) =>
  o.status === 'declined' && !o.acknowledged_at

// The buyer may cancel any time UP TO the point the order is shipped or handed
// over — i.e. while it is still pending OR approved-and-awaiting. Cancel is
// blocked once it has been shipped (farmer shipped it, or a rider has picked it
// up and is in transit) or resolved (picked up / delivered / received). There is
// no time limit — only the order's progress decides. Shared so the card, the
// order detail page and the cancel API all agree.
export const canBuyerCancel = (o: {
  status: 'pending' | 'approved' | 'declined' | 'cancelled'
  shipped_at?: string | null
  collected_at?: string | null
  received_at?: string | null
  delivery_status?: DeliveryStatus | null
}) =>
  (o.status === 'pending' || o.status === 'approved')
  && !o.shipped_at
  && !o.collected_at
  && !o.received_at
  && o.delivery_status !== 'picked_up'
  && o.delivery_status !== 'out_for_delivery'
  && o.delivery_status !== 'delivered'

export default function OrderCard({
  order,
  onComplaint,
  onFeedback,
  onAcknowledge,
  onConfirmReceipt,
  onCancel,
  busy = false,
}: {
  order: ConsumerOrder
  onComplaint: (orderCode: string) => void
  onFeedback?: (order: ConsumerOrder) => void
  // Acknowledge a declined/cancelled order (moves it to history).
  onAcknowledge?: (order: ConsumerOrder) => void
  // Confirm a shipped order was delivered/received.
  onConfirmReceipt?: (order: ConsumerOrder) => void
  // Cancel a still-pending order (opens the reason modal in the parent).
  onCancel?: (order: ConsumerOrder) => void
  // The parent is mid-request for this card (disables the action buttons).
  busy?: boolean
}) {
  const { tx, lang, L } = useLang()
  const reviewed = Boolean(order.my_review)
  const completed = isCompleted(order)
  const awaitingAck = needsAcknowledge(order)
  // The buyer confirms delivery themselves, once the farmer has marked the order
  // shipped — for every farmer-fulfilled type (self-pickup, courier, farmer-
  // shipped home delivery). Rider home deliveries never set shipped_at (the rider
  // closes them at the door), so they're naturally excluded here.
  const canConfirmReceipt = Boolean(
    onConfirmReceipt
      && order.status !== 'cancelled'
      && order.status !== 'declined'
      && !!order.shipped_at
      && !order.collected_at
      && !order.received_at,
  )
  // Feedback is only offered once the order is completed (delivered / picked up
  // / received). Showing it on a pending order is meaningless — the buyer hasn't
  // received the produce yet. Already-reviewed orders keep the button so the
  // buyer can see / edit what they left.
  const canFeedback = Boolean(onFeedback && order.produce_listing_id && (completed || reviewed))
  // Buyer may cancel any time before the order is shipped or handed over
  // (pending or approved-and-awaiting). Shared rule with the detail page + API.
  const canCancel = Boolean(onCancel && canBuyerCancel(order))

  const statusColor = (s: string) =>
    s === 'approved'
      ? 'bg-green-100 text-green-800'
      : s === 'declined'
        ? 'bg-red-100 text-red-700'
        : s === 'cancelled'
          ? 'bg-gray-200 text-gray-700'
          : 'bg-amber-100 text-amber-800'

  const deliveryStatusLabel = (s: DeliveryStatus | null | undefined) => {
    switch (s) {
      case 'assigned': return L('Rider assigned', 'రైడర్ కేటాయించబడ్డారు')
      case 'picked_up': return L('Picked up', 'తీసుకున్నారు')
      case 'out_for_delivery': return L('Out for delivery', 'డెలివరీకి బయలుదేరారు')
      case 'delivered': return L('Delivered', 'డెలివరీ అయింది')
      default: return L('Waiting for rider', 'రైడర్ కోసం వేచి ఉంది')
    }
  }

  // Home-delivery status line. With a rider assigned it's the rider flow; with
  // no rider it's farmer-shipped, so we show the Shipped → Received progress.
  const homeDeliveryLabel = () => {
    const ds = order.delivery_status
    const riderAssigned = ds != null && ds !== 'unassigned'
    if (riderAssigned) return deliveryStatusLabel(ds)
    if (order.received_at) return L('Delivered', 'డెలివరీ అయింది')
    if (order.shipped_at) return L('On the way', 'దారిలో ఉంది')
    return L('Preparing your order', 'ఆర్డర్ సిద్ధం చేస్తున్నారు')
  }

  const statusLabel = (s: string) =>
    s === 'approved' ? tx.statusConfirmed
      : s === 'declined' ? tx.statusDeclined
      : s === 'cancelled' ? tx.statusCancelled
      : tx.statusPending

  const paymentBadge = () => {
    if (!order.payment_method || order.payment_method === 'cod') return null
    // Online payments now go through Razorpay.
    if (order.payment_method === 'razorpay' && order.payment_status === 'paid') {
      return { label: L('✓ Paid online', 'ఆన్‌లైన్ చెల్లించారు'), cls: 'bg-green-100 text-green-800' }
    }
    // Manual UPI is retired — legacy UPI orders show no pay prompt.
    return null
  }

  const badge = paymentBadge()

  return (
    <Link href={`/consumer/orders/${order.id}`} className="block">
      <div className="bg-white rounded-2xl border border-gray-100 overflow-hidden active:bg-gray-50">
        <div className="p-4 space-y-2">
          <div className="flex items-start justify-between gap-2">
            <div className="min-w-0">
              <p className="font-extrabold text-gray-900 text-sm leading-tight">
                {localizeName(order.produce_name, lang) || '—'}
              </p>
              {order.order_code && (
                <p className="text-[11px] font-mono font-semibold text-gray-400 mt-0.5">
                  {order.order_code}
                </p>
              )}
              <p className="text-xs text-gray-500 mt-0.5">
                {order.quantity} {order.unit || 'kg'}
                {order.total_price ? ` · ₹${order.total_price}` : ''}
              </p>
            </div>
            <div className="flex flex-col items-end gap-1 flex-shrink-0">
              <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full whitespace-nowrap ${statusColor(order.status)}`}>
                {statusLabel(order.status)}
              </span>
              {badge && (
                <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full whitespace-nowrap ${badge.cls}`}>
                  {badge.label}
                </span>
              )}
              {order.refund_status && order.refund_status !== 'failed' && (
                <span className="text-[10px] font-bold px-2 py-0.5 rounded-full whitespace-nowrap bg-purple-100 text-purple-800">
                  💸 {order.refund_status === 'processed' ? L('Refunded', 'రీఫండ్ అయింది') : L('Refund initiated', 'రీఫండ్ ప్రారంభమైంది')}
                </span>
              )}
              {order.refund_status === 'failed' && (
                <span className="text-[10px] font-bold px-2 py-0.5 rounded-full whitespace-nowrap bg-red-100 text-red-800">
                  {L('⚠️ Refund failed', '⚠️ రీఫండ్ విఫలమైంది')}
                </span>
              )}
            </div>
          </div>

          {order.farmer && (
            <p className="flex items-center gap-1.5 text-xs text-green-700 font-semibold">
              🧑‍🌾 {tx.orderedFrom} {order.farmer.name} · {order.farmer.village}
            </p>
          )}

          {order.delivery_type === 'home_delivery' ? (
            <p className="text-xs text-blue-700 font-semibold">
              🛵 {L('Home delivery', 'హోమ్ డెలివరీ')} · {homeDeliveryLabel()}
            </p>
          ) : order.pickup_location ? (
            <p className="text-xs text-gray-500">📍 {tx.pickedUpAt}: {order.pickup_location}</p>
          ) : null}

          <p className="text-[11px] text-gray-400">
            {new Date(order.created_at).toLocaleDateString('en-IN', {
              day: 'numeric',
              month: 'short',
              year: 'numeric',
              hour: '2-digit',
              minute: '2-digit',
            })}
          </p>

          {/* Decline reason — shown only when farmer declined */}
          {order.status === 'declined' && order.decline_reason && (
            <div className="bg-red-50 border border-red-200 rounded-xl px-3 py-2 mt-1">
              <p className="text-[10px] font-bold text-red-700 uppercase tracking-wide">
                {L('Reason', 'కారణం')}
              </p>
              <p className="text-xs text-red-800 mt-0.5 leading-snug">{order.decline_reason}</p>
            </div>
          )}

          {/* Refund message — shown when a paid order was declined */}
          {order.status === 'declined' && order.refund_status === 'initiated' && (
            <div className="bg-purple-50 border border-purple-200 rounded-xl px-3 py-2 mt-1">
              <p className="text-xs text-purple-800 leading-snug">
                {L(
                  `Your payment of Rs.${order.total_price ?? 0} will be refunded to your account in 3-5 business days`,
                  `మీ చెల్లింపు Rs.${order.total_price ?? 0} 3-5 పని దినాలలో తిరిగి వస్తుంది`,
                )}
              </p>
            </div>
          )}

          {/* Confirm delivery — once the farmer marked it shipped, the buyer
              taps this to close the order. */}
          {canConfirmReceipt && (
            <button
              type="button"
              disabled={busy}
              onClick={(e) => {
                e.preventDefault()
                e.stopPropagation()
                onConfirmReceipt!(order)
              }}
              className="mt-1 w-full text-center text-xs font-bold text-white bg-green-600 rounded-xl py-2.5 active:bg-green-700 disabled:opacity-50"
            >
              {busy ? '…' : `✓ ${order.delivery_type === 'self_pickup' || !order.delivery_type ? L('Mark as Picked up', 'తీసుకున్నారు') : L('Mark as Delivered', 'డెలివరీ అయింది')}`}
            </button>
          )}

          {/* Acknowledge — a declined/cancelled order the buyer hasn't seen yet.
              Tapping it moves the order to history. */}
          {awaitingAck && onAcknowledge && (
            <button
              type="button"
              disabled={busy}
              onClick={(e) => {
                e.preventDefault()
                e.stopPropagation()
                onAcknowledge(order)
              }}
              className="mt-1 w-full text-center text-xs font-bold text-white bg-gray-700 rounded-xl py-2.5 active:bg-gray-800 disabled:opacity-50"
            >
              {busy ? '…' : `✓ ${L('Acknowledge — move to history', 'గుర్తించాను — చరిత్రకు తరలించు')}`}
            </button>
          )}

          {/* Cancel — a still-pending order within the 30-min window. Opens the
              reason modal in the parent. */}
          {canCancel && (
            <button
              type="button"
              disabled={busy}
              onClick={(e) => {
                e.preventDefault()
                e.stopPropagation()
                onCancel!(order)
              }}
              className="mt-1 w-full text-center text-xs font-bold text-red-600 bg-white border border-red-300 rounded-xl py-2.5 active:bg-red-50 disabled:opacity-50"
            >
              {busy ? '…' : `✕ ${L('Cancel order', 'ఆర్డర్ రద్దు')}`}
            </button>
          )}

          {/* Per-order actions — complaint + feedback. Both open shared modals
              pinned to this order, and stop the card's link from navigating. */}
          <div className="pt-1 flex gap-2">
            <button
              type="button"
              onClick={(e) => {
                e.preventDefault()
                e.stopPropagation()
                onComplaint(order.order_code ?? '')
              }}
              className="flex-1 text-center text-xs font-bold text-amber-700 bg-amber-50 border border-amber-200 rounded-xl py-2.5 active:bg-amber-100"
            >
              🛟 {L('Log a Complaint', 'ఫిర్యాదు')}
            </button>
            {canFeedback && (
              <button
                type="button"
                onClick={(e) => {
                  e.preventDefault()
                  e.stopPropagation()
                  onFeedback!(order)
                }}
                className={`flex-1 text-center text-xs font-bold rounded-xl py-2.5 border ${
                  reviewed
                    ? 'text-green-700 bg-green-50 border-green-200 active:bg-green-100'
                    : 'text-green-800 bg-white border-green-300 active:bg-green-50'
                }`}
              >
                {reviewed
                  ? `⭐ ${L('Feedback given', 'అభిప్రాయం ఇచ్చారు')}`
                  : `⭐ ${completed ? L('Rate harvest', 'రేటింగ్ ఇవ్వండి') : L('Give feedback', 'అభిప్రాయం')}`}
              </button>
            )}
          </div>
        </div>
      </div>
    </Link>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import { supabase } from '@/lib/supabase'
import { useLang } from '@/lib/LanguageContext'
import { isOrderPaid, isPaymentClaimed as isPaymentClaimed_ } from '@/lib/payment'

export type DeliveryStatus = 'unassigned' | 'assigned' | 'picked_up' | 'out_for_delivery' | 'delivered'

// Shared farmer-side order shape. Superset of the columns the dashboard and the
// Orders page each fetch, so the same card renders on both.
export type FarmerOrder = {
  id: string
  farmer_id: string
  order_code?: string | null
  produce_listing_id: string | null
  produce_name: string | null
  quantity: number | null
  unit: string | null
  total_price: number | null
  // Delivery + platform fees stamped on this row (cart's first row carries them,
  // 0 on the rest). Refunded IN FULL along with the produce price when the FARMER
  // declines, so the decline sheet can preview the buyer's total refund.
  delivery_fee?: number | null
  platform_fee?: number | null
  buyer_name: string | null
  buyer_phone: string | null
  pickup_location: string | null
  status: 'pending' | 'approved' | 'declined' | 'cancelled'
  payment_method?: string | null
  payment_status: string | null
  utr_number?: string | null
  decline_reason: string | null
  refund_status?: string | null
  refund_amount?: number | null
  refunded_at?: string | null
  created_at: string
  delivery_type?: 'self_pickup' | 'home_delivery' | 'courier' | null
  delivery_status?: DeliveryStatus | null
  delivery_boy_id?: string | null
  fulfillment_date?: string | null
  collected_at?: string | null
  shipped_at?: string | null
  received_at?: string | null
  // When the farmer acknowledged a buyer-cancelled order (moves it to history).
  acknowledged_at?: string | null
  // Reason the farmer gave when changing the pickup/delivery date after approval
  // (shown to the buyer). Optional — column may not exist before its migration.
  reschedule_reason?: string | null
  rescheduled_at?: string | null
}

// An approved order is "resolved" (and so leaves the farmer's active list) once:
//   self_pickup   → the buyer collected it (collected_at set)
//   courier       → the buyer confirmed receipt (received_at set); note a
//                   shipped-but-unreceived courier order stays active
//   home_delivery → rider flow: the rider delivered it (delivery_status
//                   'delivered'); farmer-ships flow: the buyer confirmed
//                   receipt (received_at set)
export function isResolved(o: FarmerOrder): boolean {
  // A buyer-cancelled order is NOT resolved until the farmer acknowledges it.
  // Until then it stays in the active list so the farmer sees the cancellation
  // instead of it silently dropping into history. Once acknowledged, it's done.
  if (o.status === 'cancelled') return !!o.acknowledged_at
  if (o.status !== 'approved') return false
  if (o.delivery_type === 'home_delivery') return o.delivery_status === 'delivered' || !!o.received_at
  if (o.delivery_type === 'courier') return !!o.received_at
  return !!o.collected_at
}

export default function OrderCard({
  order,
  processing,
  processingPaid,
  onApprove,
  onDecline,
  onAcknowledge,
  onMarkPaid,
  onUpdatePaymentStatus,
  onSetFulfillmentDate,
  onMarkShipped,
  onConfirmPickup,
  onConfirmDelivery,
}: {
  order: FarmerOrder
  processing: boolean
  processingPaid: boolean
  onApprove: (date: string) => void
  onDecline: () => void
  onAcknowledge: () => void
  onMarkPaid: () => void
  onUpdatePaymentStatus: (status: 'completed' | 'failed' | 'pending') => void
  // For a pending order, called with just the date (the gate to approval). For
  // an already-approved order, a reason is required and passed too — the buyer
  // sees it, so a date change is never silent.
  onSetFulfillmentDate: (date: string, reason?: string) => void
  // Courier / farmer-driven home delivery is marked Shipped (trust-based
  // dispatch), and the BUYER confirms receipt. A SELF-PICKUP is closed by the
  // farmer entering the buyer's 4-digit handover code (onConfirmPickup) — the
  // buyer reads it off their order page at collection. Returns an error message
  // to show inline, or null on success.
  onMarkShipped: () => void
  onConfirmPickup: (otp: string) => Promise<string | null>
  // Farmer-driven home delivery / courier: after marking Shipped, the farmer
  // types the buyer's code at the door to close the order (received_at).
  onConfirmDelivery: (otp: string) => Promise<string | null>
}) {
  const { tx, L } = useLang()
  const router = useRouter()
  const openDetails = () => router.push(`/farmer/dashboard/orders/${order.id}`)
  const isDelivery = order.delivery_type === 'home_delivery'
  const isCourier = order.delivery_type === 'courier'
  const isPickup = !isDelivery && !isCourier
  const isShipped = !!order.shipped_at
  // A home delivery is in the rider flow once a rider is assigned (delivery
  // status moved past 'unassigned'). Those stay rider-closed; home deliveries
  // with no rider are farmer-shipped, so the farmer marks them Shipped.
  const riderAssigned = isDelivery
    && order.delivery_status != null
    && order.delivery_status !== 'unassigned'
  const isApproved = order.status === 'approved'
  const fulfillmentDate = order.fulfillment_date ?? ''
  // Local (not UTC) "today" so the picker still allows today's date in IST
  // evenings. Used as the minimum selectable pickup/delivery date. Computed
  // once on mount via the lazy initializer.
  const [todayStr] = useState(() => {
    const d = new Date()
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`
  })

  // Reschedule editor state for an APPROVED order: the date is read-only until
  // the farmer taps "Change date", which reveals a date picker + a required
  // reason that the buyer will see.
  const [editingDate, setEditingDate] = useState(false)
  const [newDate, setNewDate] = useState(fulfillmentDate)
  const [rescheduleReason, setRescheduleReason] = useState('')

  // Handover-code entry. The farmer types the buyer's 4-digit code at handover;
  // a match closes the order — collected_at for self-pickup (onConfirmPickup),
  // received_at for farmer-driven delivery (onConfirmDelivery). Only one code
  // form ever renders at a time, so the state is shared. Wrong code shows inline.
  const [pickupOtp, setPickupOtp] = useState('')
  const [pickupErr, setPickupErr] = useState<string | null>(null)
  const submitCode = async (handler: (otp: string) => Promise<string | null>) => {
    setPickupErr(null)
    const err = await handler(pickupOtp)
    if (err) setPickupErr(err)
    else setPickupOtp('')
  }

  const timeAgo = (ts: string) => {
    const diff = Date.now() - new Date(ts).getTime()
    const mins = Math.floor(diff / 60000)
    if (mins < 1) return 'just now'
    if (mins < 60) return `${mins}m ago`
    const hrs = Math.floor(mins / 60)
    if (hrs < 24) return `${hrs}h ago`
    return `${Math.floor(hrs / 24)}d ago`
  }

  const isCod = !order.payment_method || order.payment_method === 'cod'
  const isUpi = order.payment_method === 'upi'
  const isPaid = isOrderPaid(order.payment_status)
  const isPaymentClaimed = isPaymentClaimed_(order.payment_status)

  // Buyer cancelled this order. It doesn't need the approve/decline/fulfillment
  // machinery — just a clear "cancelled by buyer" notice and an Acknowledge tap
  // that moves it out of the active list and into Order History.
  if (order.status === 'cancelled') {
    return (
      <div className="border border-red-200 bg-red-50/40 rounded-2xl overflow-hidden">
        <div className="p-3 space-y-2">
          <div onClick={openDetails} role="button" className="cursor-pointer space-y-2 active:opacity-70">
            <div className="flex items-start justify-between gap-2">
              <div className="min-w-0">
                <div className="flex items-center gap-1.5 flex-wrap">
                  <p className="font-extrabold text-gray-900 text-sm leading-tight">
                    {order.buyer_name || '—'}
                  </p>
                  <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-red-100 text-red-700 whitespace-nowrap">
                    {L('Cancelled by buyer', 'కొనుగోలుదారు రద్దు చేశారు')}
                  </span>
                </div>
                {order.buyer_phone && (
                  <a
                    href={`tel:+91${order.buyer_phone}`}
                    onClick={(e) => e.stopPropagation()}
                    className="text-xs font-semibold text-green-700"
                  >
                    📞 +91 {order.buyer_phone}
                  </a>
                )}
              </div>
              <div className="flex flex-col items-end flex-shrink-0 mt-0.5">
                <span className="text-[11px] text-gray-400 whitespace-nowrap">
                  {timeAgo(order.created_at)}
                </span>
                {order.order_code && (
                  <span className="text-[10px] font-mono font-semibold text-gray-400 whitespace-nowrap">
                    {order.order_code}
                  </span>
                )}
              </div>
            </div>

            <div className="flex flex-wrap items-center gap-1.5 text-sm">
              <span className="font-semibold text-gray-800">{order.produce_name || '—'}</span>
              <span className="text-gray-300">·</span>
              <span className="text-gray-600">{order.quantity} {order.unit || 'kg'}</span>
              {order.total_price != null && order.total_price > 0 && (
                <>
                  <span className="text-gray-300">·</span>
                  <span className="font-bold text-gray-500 line-through">₹{order.total_price}</span>
                </>
              )}
            </div>
          </div>

          {order.decline_reason && (
            <div className="bg-white border border-red-200 rounded-xl px-3 py-2">
              <p className="text-[10px] font-bold text-red-700 uppercase tracking-wide">
                {L('Reason', 'కారణం')}
              </p>
              <p className="text-xs text-red-800 mt-0.5 leading-snug">{order.decline_reason}</p>
            </div>
          )}

          <button
            onClick={onAcknowledge}
            disabled={processing}
            className="w-full bg-gray-700 text-white font-bold py-2.5 rounded-xl text-sm active:bg-gray-800 disabled:opacity-50"
          >
            {processing ? '…' : `✓ ${L('Acknowledge — move to history', 'గుర్తించాను — చరిత్రకు తరలించు')}`}
          </button>
        </div>
      </div>
    )
  }

  return (
    <div className={`border rounded-2xl overflow-hidden ${isApproved ? 'border-green-200 bg-green-50/30' : 'border-gray-200'}`}>
      <div className="p-3 space-y-1.5">
        {/* Tapping the order summary opens the full order details page. The
            phone link below stops propagation so calling never navigates. */}
        <div onClick={openDetails} role="button" className="cursor-pointer space-y-1.5 active:opacity-70">
          <div className="flex items-start justify-between gap-2">
            <div className="min-w-0">
              <div className="flex items-center gap-1.5 flex-wrap">
                <p className="font-extrabold text-gray-900 text-sm leading-tight">
                  {order.buyer_name || '—'}
                </p>
                {isApproved && (
                  <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-green-100 text-green-800 whitespace-nowrap">
                    {tx.statusApproved}
                  </span>
                )}
              </div>
              {order.buyer_phone && (
                <a
                  href={`tel:+91${order.buyer_phone}`}
                  onClick={(e) => e.stopPropagation()}
                  className="text-xs font-semibold text-green-700"
                >
                  📞 +91 {order.buyer_phone}
                </a>
              )}
            </div>
            <div className="flex items-center gap-1.5 flex-shrink-0 mt-0.5">
              {isCod && (
                <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full whitespace-nowrap ${
                  isPaid ? 'bg-green-100 text-green-800' : 'bg-amber-100 text-amber-800'
                }`}>
                  {isPaid ? `✓ ${tx.paymentReceived}` : tx.codBadge}
                </span>
              )}
              {isUpi && (
                <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full whitespace-nowrap ${
                  isPaid ? 'bg-green-100 text-green-800'
                  : isPaymentClaimed ? 'bg-orange-100 text-orange-800'
                  : 'bg-blue-100 text-blue-700'
                }`}>
                  {isPaid ? '✓ UPI Paid' : isPaymentClaimed ? '⏳ Buyer Paid — Verify' : '📲 UPI'}
                </span>
              )}
              <div className="flex flex-col items-end">
                <span className="text-[11px] text-gray-400 whitespace-nowrap">
                  {timeAgo(order.created_at)}
                </span>
                {order.order_code && (
                  <span className="text-[10px] font-mono font-semibold text-gray-400 whitespace-nowrap">
                    {order.order_code}
                  </span>
                )}
              </div>
            </div>
          </div>

          <div className="flex flex-wrap items-center gap-1.5 text-sm">
            <span className="font-semibold text-gray-800">{order.produce_name || '—'}</span>
            <span className="text-gray-300">·</span>
            <span className="text-gray-600">{order.quantity} {order.unit || 'kg'}</span>
            {order.total_price != null && order.total_price > 0 && (
              <>
                <span className="text-gray-300">·</span>
                <span className="font-bold text-green-700">₹{order.total_price}</span>
              </>
            )}
          </div>

          {order.pickup_location && (
            <p className="text-xs text-gray-500">📍 {order.pickup_location}</p>
          )}

          <p className="text-[11px] font-semibold text-green-700 pt-0.5">
            {L('View full details', 'పూర్తి వివరాలు చూడండి')} →
          </p>
        </div>

        {order.delivery_type === 'home_delivery' && (
          <DeliveryTagForFarmer order={order} />
        )}

        {/* Pickup / delivery date. */}
        <div className="pt-1">
          <label className="text-[11px] font-bold text-gray-600 block mb-1">
            📅 {isPickup ? tx.pickupDateLabel : tx.deliveryDateLabel}
          </label>

          {!isApproved ? (
            // Pending: the date is the gate to approval — the farmer picks it,
            // then confirms below. No reason needed for the first choice.
            <input
              type="date"
              value={fulfillmentDate}
              min={todayStr}
              onChange={(e) => onSetFulfillmentDate(e.target.value)}
              className="w-full border border-gray-200 rounded-xl px-3 py-2.5 text-sm bg-white focus:border-green-500 focus:outline-none"
            />
          ) : !editingDate ? (
            // Approved: the date is locked (read-only). Changing it is a
            // deliberate action that requires a reason the buyer will see.
            <>
              <p className="text-sm font-bold text-gray-900">
                {fulfillmentDate
                  ? new Date(`${fulfillmentDate}T00:00:00`).toLocaleDateString('en-IN', {
                      weekday: 'short', day: 'numeric', month: 'short', year: 'numeric',
                    })
                  : '—'}
              </p>
              {fulfillmentDate && !isShipped && (
                <p className="text-[11px] font-semibold text-green-700 mt-1">
                  ⏳ {isPickup ? tx.awaitingPickup : tx.awaitingDelivery}
                </p>
              )}
              <button
                type="button"
                onClick={() => { setNewDate(fulfillmentDate); setRescheduleReason(''); setEditingDate(true) }}
                disabled={processing}
                className="mt-2 text-[11px] font-bold text-green-700 underline disabled:opacity-50"
              >
                {L('Change date', 'తేదీ మార్చండి')}
              </button>
            </>
          ) : (
            // Reschedule editor: new date + a required reason for the buyer.
            <div className="space-y-2 bg-amber-50 border border-amber-200 rounded-xl p-2.5">
              <input
                type="date"
                value={newDate}
                min={todayStr}
                onChange={(e) => setNewDate(e.target.value)}
                className="w-full border border-gray-200 rounded-xl px-3 py-2.5 text-sm bg-white focus:border-green-500 focus:outline-none"
              />
              <textarea
                value={rescheduleReason}
                onChange={(e) => setRescheduleReason(e.target.value.slice(0, 200))}
                rows={2}
                placeholder={L('Reason for the new date (the buyer will see this)', 'కొత్త తేదీకి కారణం (కొనుగోలుదారు చూస్తారు)')}
                className="w-full border border-gray-200 rounded-xl px-3 py-2 text-sm resize-none focus:border-green-500 focus:outline-none"
              />
              <div className="grid grid-cols-2 gap-2">
                <button
                  type="button"
                  onClick={() => setEditingDate(false)}
                  className="border border-gray-300 text-gray-600 font-bold py-2 rounded-xl text-xs active:bg-gray-50"
                >
                  {tx.cancelBtn}
                </button>
                <button
                  type="button"
                  disabled={processing || !newDate || !rescheduleReason.trim() || newDate === fulfillmentDate}
                  onClick={() => { onSetFulfillmentDate(newDate, rescheduleReason.trim()); setEditingDate(false) }}
                  className="bg-green-600 text-white font-bold py-2 rounded-xl text-xs active:bg-green-700 disabled:opacity-50"
                >
                  {L('Save new date', 'కొత్త తేదీ సేవ్')}
                </button>
              </div>
              {newDate && newDate !== fulfillmentDate && !rescheduleReason.trim() && (
                <p className="text-[11px] text-amber-700">{L('Add a reason so the buyer knows why.', 'కొనుగోలుదారుకు కారణం తెలియజేయండి.')}</p>
              )}
            </div>
          )}
        </div>
      </div>

      {isUpi && isPaymentClaimed && (
        <div className="mx-3 mb-2 bg-orange-50 border border-orange-200 rounded-xl px-3 py-3 space-y-2.5">
          <div>
            <p className="text-xs font-bold text-orange-800">
              📲 Buyer says they paid via UPI
            </p>
            <p className="text-[11px] text-orange-700 mt-0.5">
              Open your UPI app and confirm you received ₹{order.total_price ?? '?'} from {order.buyer_name || 'buyer'}.
            </p>
            {order.utr_number && (
              <p className="text-[11px] text-orange-700 mt-0.5">
                UTR: <span className="font-mono font-semibold">{order.utr_number}</span>
              </p>
            )}
          </div>
          <p className="text-xs font-bold text-gray-700">
            {L('Update Payment Status', 'చెల్లింపు స్థితి నవీకరించండి')}
          </p>
          <p className="text-[11px] text-gray-500 -mt-1">{tx.receivedApprovesOrderHint}</p>
          <div className="grid grid-cols-3 gap-2">
            <button
              onClick={() => onUpdatePaymentStatus('completed')}
              disabled={processingPaid}
              className="bg-green-700 text-white font-bold py-2.5 rounded-xl text-[11px] leading-tight disabled:opacity-50 active:bg-green-800 px-1"
            >
              {L('✓ Received & Approve', 'అందింది & ఆమోదం')}
            </button>
            <button
              onClick={() => onUpdatePaymentStatus('failed')}
              disabled={processingPaid}
              className="border-2 border-red-300 text-red-600 font-bold py-2.5 rounded-xl text-xs disabled:opacity-50 active:bg-red-50"
            >
              {L('✕ Not Received', 'రాలేదు')}
            </button>
            <button
              onClick={() => onUpdatePaymentStatus('pending')}
              disabled={processingPaid}
              className="border-2 border-amber-300 text-amber-700 font-bold py-2.5 rounded-xl text-xs disabled:opacity-50 active:bg-amber-50"
            >
              {L('⏳ Pending', 'పెండింగ్')}
            </button>
          </div>
        </div>
      )}

      <div className="px-3 pb-3 space-y-2">
        {!isApproved ? (
          <>
            {/* Pending: confirming the chosen pickup/delivery date approves the
                order. The confirm button stays disabled until a date is set. */}
            <div className={`grid gap-2 ${isUpi && isPaymentClaimed ? 'grid-cols-1' : 'grid-cols-2'}`}>
              {!(isUpi && isPaymentClaimed) && (
                <button
                  onClick={() => onApprove(fulfillmentDate)}
                  disabled={processing || !fulfillmentDate}
                  className="bg-green-600 text-white font-bold py-3 rounded-xl text-sm active:bg-green-700 disabled:opacity-50"
                >
                  {processing ? tx.approving : (isPickup ? tx.confirmPickupDate : tx.confirmDeliveryDate)}
                </button>
              )}
              <button
                onClick={onDecline}
                disabled={processing}
                className="border-2 border-red-300 text-red-600 font-bold py-3 rounded-xl text-sm active:bg-red-50 disabled:opacity-50"
              >
                {processing ? tx.declining : `✕ ${tx.decline}`}
              </button>
            </div>
            {!fulfillmentDate && !(isUpi && isPaymentClaimed) && (
              <p className="text-[11px] text-gray-500 text-center">{tx.chooseDateToApprove}</p>
            )}
          </>
        ) : isDelivery && riderAssigned ? (
          // Approved home-delivery in the rider flow: the farmer can still
          // cancel; the rider closes it out at the door.
          <button
            onClick={onDecline}
            disabled={processing}
            className="w-full border-2 border-red-300 text-red-600 font-bold py-2.5 rounded-xl text-sm active:bg-red-50 disabled:opacity-50"
          >
            {processing ? tx.declining : `✕ ${tx.decline}`}
          </button>
        ) : isShipped ? (
          isDelivery ? (
            // Shipped HOME DELIVERY: the farmer does NOT confirm delivery. A
            // delivery person hands it over, and the CUSTOMER closes the order
            // with "Mark Delivered" from their own order page. (No delivery
            // module yet, so we just show a passive status here — see the
            // "remove farmer code-confirm for home delivery" card.)
            <div className="bg-green-50 border border-green-200 rounded-xl px-3 py-2.5 text-center space-y-1">
              <p className="text-[11px] font-bold text-amber-800">🚚 {L('Shipped — on the way', 'షిప్ అయింది — దారిలో')}</p>
              <p className="text-xs text-green-800 leading-snug">
                {L('The customer will confirm delivery from their order page.', 'కస్టమర్ వారి ఆర్డర్ పేజీ నుండి డెలివరీని ధృవీకరిస్తారు.')}
              </p>
            </div>
          ) : (
            // Shipped COURIER: the farmer types the buyer's 4-digit code at
            // handover to close the order (received_at) — verified handover, same
            // as self-pickup. Home delivery is handled above (no farmer code).
            <div className="bg-green-50 border border-green-200 rounded-xl px-3 py-2.5 space-y-2">
              <p className="text-[11px] font-bold text-amber-800 text-center">🚚 {L('Shipped — on the way', 'షిప్ అయింది — దారిలో')}</p>
              <p className="text-xs font-bold text-green-800 text-center">
                {L('Enter the customer’s code at delivery', 'డెలివరీ సమయంలో కస్టమర్ కోడ్ నమోదు చేయండి')}
              </p>
              <div className="flex gap-2">
                <input
                  inputMode="numeric"
                  pattern="\d*"
                  maxLength={4}
                  value={pickupOtp}
                  onChange={(e) => { setPickupOtp(e.target.value.replace(/\D/g, '').slice(0, 4)); setPickupErr(null) }}
                  placeholder="0000"
                  className="flex-1 min-w-0 text-center text-lg font-bold tracking-[0.4em] border border-green-300 rounded-lg py-2 focus:outline-none focus:ring-2 focus:ring-green-500"
                />
                <button
                  onClick={() => submitCode(onConfirmDelivery)}
                  disabled={processing || pickupOtp.length !== 4}
                  className="px-4 bg-green-700 text-white font-bold rounded-lg text-sm active:bg-green-800 disabled:opacity-50"
                >
                  {processing ? '…' : L('Confirm', 'ధృవీకరించు')}
                </button>
              </div>
              {pickupErr && <p className="text-[11px] text-red-600 text-center font-semibold">{pickupErr}</p>}
              <p className="text-[10px] text-green-700 text-center leading-snug">
                {L('Ask the customer to read the 4-digit code from their order page.', 'కస్టమర్‌ను వారి ఆర్డర్ పేజీలోని 4-అంకెల కోడ్ చదవమని అడగండి.')}
              </p>
            </div>
          )
        ) : isPickup ? (
          // Approved SELF-PICKUP: the farmer closes the order by entering the
          // buyer's 4-digit handover code (shown only on the buyer's own order
          // page). A match stamps collected_at and resolves the order. There is
          // no "mark picked up" tap — the code proves the customer was actually
          // present to collect, so the farmer can't close it alone.
          <>
            <div className="bg-green-50 border border-green-200 rounded-xl px-3 py-2.5 space-y-2">
              <p className="text-xs font-bold text-green-800 text-center">
                {L('Enter the customer’s pickup code', 'కస్టమర్ పికప్ కోడ్ నమోదు చేయండి')}
              </p>
              <div className="flex gap-2">
                <input
                  inputMode="numeric"
                  pattern="\d*"
                  maxLength={4}
                  value={pickupOtp}
                  onChange={(e) => { setPickupOtp(e.target.value.replace(/\D/g, '').slice(0, 4)); setPickupErr(null) }}
                  placeholder="0000"
                  className="flex-1 min-w-0 text-center text-lg font-bold tracking-[0.4em] border border-green-300 rounded-lg py-2 focus:outline-none focus:ring-2 focus:ring-green-500"
                />
                <button
                  onClick={() => submitCode(onConfirmPickup)}
                  disabled={processing || pickupOtp.length !== 4}
                  className="px-4 bg-green-700 text-white font-bold rounded-lg text-sm active:bg-green-800 disabled:opacity-50"
                >
                  {processing ? '…' : L('Confirm', 'ధృవీకరించు')}
                </button>
              </div>
              {pickupErr && <p className="text-[11px] text-red-600 text-center font-semibold">{pickupErr}</p>}
              <p className="text-[10px] text-green-700 text-center leading-snug">
                {L('Ask the customer to read the 4-digit code from their order page.', 'కస్టమర్‌ను వారి ఆర్డర్ పేజీలోని 4-అంకెల కోడ్ చదవమని అడగండి.')}
              </p>
            </div>
            <button
              onClick={onDecline}
              disabled={processing}
              className="w-full border-2 border-red-300 text-red-600 font-bold py-2.5 rounded-xl text-sm active:bg-red-50 disabled:opacity-50"
            >
              {processing ? tx.declining : `✕ ${tx.decline}`}
            </button>
          </>
        ) : (
          // Approved courier / farmer-driven home delivery (rider deliveries were
          // handled above). The farmer marks it Shipped (trust-based dispatch);
          // the BUYER then confirms receipt from their order page, which closes it.
          <>
            <button
              onClick={onMarkShipped}
              disabled={processing}
              className="w-full bg-amber-600 text-white font-bold py-2.5 rounded-xl text-sm active:bg-amber-700 disabled:opacity-50"
            >
              {processing ? '…' : L('🚚 Mark Shipped', '🚚 షిప్ చేయబడింది')}
            </button>
            <button
              onClick={onDecline}
              disabled={processing}
              className="w-full border-2 border-red-300 text-red-600 font-bold py-2.5 rounded-xl text-sm active:bg-red-50 disabled:opacity-50"
            >
              {processing ? tx.declining : `✕ ${tx.decline}`}
            </button>
          </>
        )}
        {isCod && !isPaid && (
          <button
            onClick={onMarkPaid}
            disabled={processingPaid}
            className="w-full bg-amber-500 text-white font-bold py-3 rounded-xl text-sm active:bg-amber-600 disabled:opacity-50 flex items-center justify-center gap-1.5"
          >
            💵 {processingPaid ? tx.markingPaid : tx.markPaid}
          </button>
        )}
      </div>
    </div>
  )
}

/* ─── Home-delivery rider tag ──────────────────────────────── */
function DeliveryTagForFarmer({ order }: { order: FarmerOrder }) {
  const [rider, setRider] = useState<{ name: string | null; phone: string } | null>(null)
  const riderId = order.delivery_boy_id ?? null

  useEffect(() => {
    if (!riderId) { setRider(null); return }
    let cancelled = false
    supabase
      .from('delivery_boys')
      .select('name, phone')
      .eq('id', riderId)
      .maybeSingle()
      .then(({ data }) => {
        if (cancelled || !data) return
        setRider({ name: data.name ?? null, phone: data.phone as string })
      })
    return () => { cancelled = true }
  }, [riderId])

  const statusText = (() => {
    switch (order.delivery_status) {
      case 'assigned': return 'Rider assigned'
      case 'picked_up': return 'Picked up'
      case 'out_for_delivery': return 'Out for delivery'
      case 'delivered': return 'Delivered'
      default: return 'Waiting for rider'
    }
  })()

  return (
    <div className="bg-blue-50 border border-blue-200 rounded-xl px-3 py-2 mt-1 space-y-1.5">
      <p className="text-[10px] font-bold text-blue-800 uppercase tracking-wide">
        🛵 Home delivery · {statusText}
      </p>
      {rider ? (
        <div className="flex items-center justify-between gap-2">
          <div className="min-w-0">
            <p className="text-xs font-bold text-gray-900 truncate">{rider.name || 'Rider'}</p>
            <p className="text-[11px] text-gray-500">For pickup coordination</p>
          </div>
          <a
            href={`tel:${rider.phone}`}
            className="bg-blue-600 text-white font-bold text-xs px-3 py-2 rounded-xl whitespace-nowrap active:bg-blue-700"
          >
            📞 Call · {rider.phone}
          </a>
        </div>
      ) : (
        <p className="text-[11px] text-blue-700">
          A delivery boy will pick up the order. You&apos;ll see their contact here when assigned.
        </p>
      )}
    </div>
  )
}

)

const { data: orders, error } = await supabase
  .from('orders')
  .select(
    'id, order_code, produce_name, produce_listing_id, quantity, unit, total_price, platform_fee, pickup_location, status, payment_method, payment_status, refund_status, refund_id, refund_amount, refunded_at, decline_reason, payment_proof_path, created_at, farmer_id, delivery_type, delivery_status, delivery_address, delivery_landmark, delivery_pincode, delivery_alt_phone, delivery_boy_id, handover_otp, assigned_at, picked_up_at, out_for_delivery_at, delivered_at, shipped_at, collected_at, received_at, acknowledged_at',
  )
  .eq('consumer_id', session.consumerId)
  .order('created_at', { ascending: false })
  .limit(100)

if (error) {
  return NextResponse.json({ error: error.message }, { status: 500 })
}

