'use client'

import { useEffect, useState } from 'react'
import { useRouter } from 'next/navigation'
import { supabase } from '@/lib/supabase'
import { useLang } from '@/lib/LanguageContext'
import { localizeName } from '@/lib/localizeName'
import { harvestClock } from '@/lib/harvest'

// "Fresh Harvests near you" — a compact table of the most recent harvests,
// newest pick first (descending harvested_at). Each row shows the harvest name
// and its "Harvested 2h ago" clock; tapping a row opens the complete harvest
// details (the produce page). Reads the `harvests` table (see
// scripts/harvests-migration.sql) and silently renders nothing when the table /
// migration isn't present yet, or when there are no fresh harvests.

type Listing = {
  id: string
  name: string
  emoji?: string | null
  status?: string | null
}

type HarvestRow = {
  id: string
  harvested_at: string
  produce_listing_id: string
  // PostgREST embeds the parent listing as an object (many-to-one).
  produce_listings?: Listing | Listing[] | null
}

const DAY = 86_400_000

export default function FreshHarvestsTable() {
  const { lang, L } = useLang()
  const router = useRouter()
  const [rows, setRows] = useState<HarvestRow[]>([])
  const [loaded, setLoaded] = useState(false)

  useEffect(() => {
    let cancelled = false
    // Same window as the Today's Harvest feed: recently picked (buyable now) plus
    // a few days of upcoming pre-book harvests — but strictly newest-first.
    const start = new Date(Date.now() - 2 * DAY).toISOString()
    const end = new Date(Date.now() + 3 * DAY).toISOString()
    supabase
      .from('harvests')
      .select('id, harvested_at, produce_listing_id, produce_listings!inner(id, name, emoji, status)')
      .gte('harvested_at', start)
      .lte('harvested_at', end)
      .eq('produce_listings.status', 'available')
      .order('harvested_at', { ascending: false })
      .limit(12)
      .then(({ data }) => {
        if (cancelled) return
        setRows((data ?? []) as HarvestRow[])
        setLoaded(true)
      })
    return () => { cancelled = true }
  }, [])

  // One listing from the embed (handle either object or single-element array).
  const listingOf = (r: HarvestRow): Listing | null => {
    const l = r.produce_listings
    if (!l) return null
    return Array.isArray(l) ? (l[0] ?? null) : l
  }

  if (!loaded || rows.length === 0) return null

  return (
    <div className="bg-white rounded-2xl shadow-xl overflow-hidden">
      <div className="px-4 pt-4 pb-2 flex items-baseline justify-between">
        <h2 className="text-base font-extrabold text-gray-900">
          🌾 {L('Fresh Harvests near you', 'మీ దగ్గర తాజా కోతలు')}
        </h2>
        <span className="text-[11px] text-gray-500">{L('Freshest first', 'తాజావి ముందు')}</span>
      </div>

      <table className="w-full text-left border-collapse">
        <thead>
          <tr className="text-[10px] uppercase tracking-wide text-gray-400 border-b border-gray-100">
            <th className="font-bold px-4 py-2">{L('Harvest', 'కోత')}</th>
            <th className="font-bold px-4 py-2 text-right">{L('When', 'ఎప్పుడు')}</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((r) => {
            const item = listingOf(r)
            if (!item) return null
            return (
              <tr
                key={r.id}
                onClick={() => router.push(`/consumer/produce/${item.id}`)}
                className="border-b border-gray-50 last:border-0 cursor-pointer active:bg-green-50"
              >
                <td className="px-4 py-3">
                  <span className="flex items-center gap-1.5 min-w-0">
                    <span className="text-lg shrink-0">{item.emoji || '🌿'}</span>
                    <span className="text-sm font-bold text-gray-900 truncate">
                      {localizeName(item.name, lang)}
                    </span>
                  </span>
                </td>
                <td className="px-4 py-3 text-right align-middle">
                  <span className="text-[11px] font-semibold text-green-700 whitespace-nowrap">
                    ⏱ {harvestClock(r.harvested_at, L)}
                  </span>
                </td>
              </tr>
            )
          })}
        </tbody>
      </table>
    </div>
  )
}

