  const skip = () => {
    clearTimers()
    setPhase('done')
  }

  if (phase === 'done') return null

  return (
    <div
      onClick={skip}
      role="presentation"
      aria-hidden
      className={`splash-overlay fixed inset-0 z-[200] flex flex-col items-center justify-center px-6 text-center select-none ${
